package com.example;

import com.google.inject.Provides;
import java.io.IOException;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;

@PluginDescriptor(
        name = "Shinigami Eyes",
        description = "Shows Corrupted Gauntlet KC above nearby players in the Gauntlet lobby",
        tags = {"gauntlet", "overlay", "kc"}
)
public class ShinigamiEyesPlugin extends Plugin
{
    private static final int TARGET_REGION_ID = 12127;
    private static final int NOT_FOUND = -1;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ShinigamiEyesOverlay overlay;

    @Inject
    private ShinigamiEyesConfig config;

    @Inject
    private HiscoreClient hiscoreClient;

    @Inject
    private ScheduledExecutorService executor;

    private ScheduledFuture<?> drainTask;

    // Names currently queued or already resolved this session — ensures
    // each player is only ever looked up once per client session.
    private final Queue<String> lookupQueue = new ConcurrentLinkedQueue<>();
    private final Set<String> queuedOrDone = ConcurrentHashMap.newKeySet();
    private final ConcurrentHashMap<String, Integer> kcCache = new ConcurrentHashMap<>();

    @Provides
    ShinigamiEyesConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ShinigamiEyesConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        // Drains at most one name from the queue every 300ms, so lookups
        // trickle out one-at-a-time instead of bursting.
        drainTask = executor.scheduleWithFixedDelay(this::drainOne, 0, 300, TimeUnit.MILLISECONDS);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        if (drainTask != null)
        {
            drainTask.cancel(true);
        }
        lookupQueue.clear();
        queuedOrDone.clear();
        kcCache.clear();
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (!isInTargetArea())
        {
            return;
        }

        for (Player p : client.getPlayers())
        {
            if (p == null || p == client.getLocalPlayer())
            {
                continue;
            }

            String name = p.getName();
            // queuedOrDone.add() returns false if the name is already present,
            // so each player name is only ever added to the queue once.
            if (name != null && queuedOrDone.add(name))
            {
                lookupQueue.add(name);
            }
        }
    }

    private void drainOne()
    {
        String name = lookupQueue.poll();
        if (name == null)
        {
            return;
        }

        try
        {
            HiscoreResult result = hiscoreClient.lookup(name, HiscoreEndpoint.NORMAL);
            Skill skill = result.getSkill(HiscoreSkill.THE_CORRUPTED_GAUNTLET);
            int kc = skill != null ? skill.getLevel() : NOT_FOUND;
            kcCache.put(name, kc);
        }
        catch (IOException e)
        {
            // Transient failure (timeout, brief rate limit). Remove from
            // queuedOrDone so this specific player can be retried later —
            // this is the only case where a "poll" doesn't count as final.
            queuedOrDone.remove(name);
        }
    }

    public boolean isInTargetArea()
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return false;
        }

        return client.getLocalPlayer().getWorldLocation().getRegionID() == TARGET_REGION_ID;
    }

    /**
     * Returns display text for a player, or null if no data yet / not found.
     */
    public String getDisplayText(String playerName)
    {
        if (playerName == null)
        {
            return null;
        }

        Integer kc = kcCache.get(playerName);
        if (kc == null)
        {
            return null; // still queued/not looked up yet
        }
        if (kc == NOT_FOUND)
        {
            return "0"; // not on hiscores — treat as 0
        }
        return String.valueOf(kc);
    }
}

package com.example;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ShinigamiEyesOverlay extends Overlay
{
    private static final Font SHINIGAMI_FONT = new Font("Serif", Font.ITALIC | Font.BOLD, 16);
    private static final int TEXT_HEIGHT_OFFSET = 20;

    private final Client client;
    private final ShinigamiEyesPlugin plugin;
    private final ShinigamiEyesConfig config;

    @Inject
    private ShinigamiEyesOverlay(Client client, ShinigamiEyesPlugin plugin, ShinigamiEyesConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isInTargetArea())
        {
            return null;
        }

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setFont(SHINIGAMI_FONT);

        Player localPlayer = client.getLocalPlayer();
        long time = System.currentTimeMillis();

        for (Player p : client.getPlayers())
        {
            if (p == null || p == localPlayer)
            {
                continue;
            }

            String text = plugin.getDisplayText(p.getName());
            if (text == null)
            {
                continue;
            }

            double phase = (p.getName().hashCode() % 1000) / 1000.0 * Math.PI * 2;
            float floatOffset = (float) (Math.sin(time / 400.0 + phase) * 4);

            net.runelite.api.Point base = p.getCanvasTextLocation(graphics, text, p.getLogicalHeight() + TEXT_HEIGHT_OFFSET);
            if (base == null)
            {
                continue;
            }

            int x = base.getX();
            int y = base.getY() + Math.round(floatOffset);

            drawSmokeyText(graphics, x, y, text, config.textColor());
        }

        return null;
    }

    private void drawSmokeyText(Graphics2D graphics, int x, int y, String text, Color baseColor)
    {
        int[][] offsets = {
                {-2, -2}, {2, -2}, {-2, 2}, {2, 2},
                {-1, 0}, {1, 0}, {0, -1}, {0, 1},
                {-3, 0}, {3, 0}, {0, -3}, {0, 3}
        };

        Color glow = new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 35);
        graphics.setColor(glow);
        for (int[] off : offsets)
        {
            graphics.drawString(text, x + off[0], y + off[1]);
        }

        Color outline = new Color(0, 0, 0, 120);
        graphics.setColor(outline);
        graphics.drawString(text, x + 1, y + 1);

        Color core = new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 230);
        graphics.setColor(core);
        graphics.drawString(text, x, y);
    }
}

package com.example;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("shinigamieyes")
public interface ShinigamiEyesConfig extends Config
{
    @ConfigItem(
            keyName = "textColor",
            name = "Text color",
            description = "Color of the overlay text"
    )
    default Color textColor()
    {
        return Color.RED;
    }
}
